// Живой экран зала: на размытом космическом фоне рисуем постер, фильм, сеанс и выбранные места.
// Android передаёт данные через setScreen({...}); холст потом становится текстурой экрана в 3D.
var KadrScreen = (function () {
  var W = 2100, H = 900;
  var cv = document.createElement('canvas'); cv.width = W; cv.height = H;
  var g = cv.getContext('2d');
  var bg = null, hello = null, info = null, version = 0;
  var filmPoster = null;
  var ACC = '#FF5A4E', TXT = '#F5F3EE', MUTED = '#A9A6B4';

  function fontsReady() {
    var list = [['Mont', 'data:font/ttf;base64,', '800'], ['Mont', 'data:font/ttf;base64,', '700'],
                ['InterK', 'data:font/ttf;base64,', '500'], ['InterK', 'data:font/ttf;base64,', '600']];
    return Promise.all(list.map(function (f) {
      var ff = new FontFace(f[0], 'url(' + f[1] + ')', { weight: f[2] });
      document.fonts.add(ff); return ff.load().catch(function () {});
    }));
  }
  function rr(x, y, w, h, r) { g.beginPath(); g.moveTo(x + r, y); g.arcTo(x + w, y, x + w, y + h, r); g.arcTo(x + w, y + h, x, y + h, r); g.arcTo(x, y + h, x, y, r); g.arcTo(x, y, x + w, y, r); g.closePath(); }
  function hex(c, a) { c = (c || '#3A2E4F').replace('#', ''); var n = parseInt(c, 16); return 'rgba(' + (n >> 16 & 255) + ',' + (n >> 8 & 255) + ',' + (n & 255) + ',' + a + ')'; }
  function rnd(seed) { return function () { seed = (seed * 16807) % 2147483647; return (seed - 1) / 2147483646; }; }
  function fitText(txt, maxW, size, weight, family) {
    do { g.font = weight + ' ' + size + 'px ' + family; size -= 4; } while (g.measureText(txt).width > maxW && size > 20);
  }
  function wrap2(txt, maxW) {
    var words = txt.toUpperCase().split(' '), lines = [''];
    words.forEach(function (w) { var t = lines[lines.length - 1] ? lines[lines.length - 1] + ' ' + w : w; if (g.measureText(t).width > maxW && lines[lines.length - 1]) lines.push(w); else lines[lines.length - 1] = t; });
    return lines.slice(0, 3);
  }

  function logo(x, y, s) {   // значок «Кадр»: кадр плёнки с кнопкой play
    g.save(); g.translate(x, y); g.scale(s / 120, s / 120);
    g.lineWidth = 9; g.strokeStyle = ACC; rr(8, 8, 104, 104, 24); g.stroke();
    g.fillStyle = ACC; [22, 88].forEach(function (hx) { [24, 53, 82].forEach(function (hy) { rr(hx, hy, 10, 14, 3); g.fill(); }); });
    g.fillStyle = TXT; g.beginPath(); g.moveTo(48, 40); g.lineTo(48, 80); g.lineTo(80, 60); g.closePath(); g.fill();
    g.restore();
  }

  function poster(x, y, w, h, d) {
    g.save(); rr(x, y, w, h, 34); g.clip();
    if (filmPoster && filmPoster.naturalWidth) {
      var scale = Math.max(w / filmPoster.naturalWidth, h / filmPoster.naturalHeight);
      var imageW = filmPoster.naturalWidth * scale, imageH = filmPoster.naturalHeight * scale;
      g.drawImage(filmPoster, x + (w - imageW) / 2, y + (h - imageH) / 2, imageW, imageH);
    } else {
      placeholderPoster(x, y, w, h, d);
    }
    g.restore();
    g.strokeStyle = 'rgba(255,255,255,0.10)'; g.lineWidth = 2; rr(x, y, w, h, 34); g.stroke();
  }

  function placeholderPoster(x, y, w, h, d) {
    var ih = h * 0.62, R = rnd((d.title || 'x').length * 977 + 13);
    var gr = g.createLinearGradient(0, y, 0, y + ih);
    gr.addColorStop(0, '#05060C'); gr.addColorStop(0.55, hex(d.color, 1)); gr.addColorStop(1, '#0A0B12');
    g.fillStyle = gr; g.fillRect(x, y, w, ih);
    for (var i = 0; i < 160; i++) { g.fillStyle = 'rgba(255,255,255,' + (0.2 + R() * 0.6) + ')'; g.fillRect(x + R() * w, y + R() * ih * 0.7, 1.6 + R() * 1.6, 1.6 + R() * 1.6); }
    // световые полосы (как сияние) в цвете фильма
    for (var k = 0; k < 3; k++) {
      var cy = y + ih * (0.22 + k * 0.12), amp = ih * 0.06;
      for (var sx = 0; sx < w; sx += 6) {
        var yy = cy + Math.sin(sx / w * 6.0 + k * 1.7) * amp;
        var gg = g.createLinearGradient(0, yy - 90, 0, yy + 40);
        gg.addColorStop(0, 'rgba(80,220,190,0)'); gg.addColorStop(0.7, k === 1 ? 'rgba(120,140,255,0.16)' : 'rgba(80,230,190,0.18)'); gg.addColorStop(1, 'rgba(80,220,190,0)');
        g.fillStyle = gg; g.fillRect(x + sx, yy - 90, 5, 130);
      }
    }
    // горы
    [[0.62, '#1E2C3E'], [0.74, '#152030'], [0.86, '#0C131D']].forEach(function (m, mi) {
      g.fillStyle = m[1]; g.beginPath(); g.moveTo(x, y + ih);
      for (var sx = 0; sx <= w; sx += 20) g.lineTo(x + sx, y + ih * m[0] + Math.sin(sx / w * (4 + mi * 2) + mi) * ih * 0.07 + Math.sin(sx / w * 13 + mi * 3) * ih * 0.02);
      g.lineTo(x + w, y + ih); g.closePath(); g.fill();
    });
    g.fillStyle = '#0A0A0E'; g.fillRect(x, y + ih, w, h - ih);
    g.fillStyle = TXT; g.font = '800 64px Mont'; g.textBaseline = 'alphabetic';
    var lines = wrap2(d.title || '', w - 80);
    var size = lines.length > 2 ? 52 : 64; g.font = '800 ' + size + 'px Mont';
    var top = y + h - 78 - (lines.length - 1) * (size + 8);
    lines.forEach(function (l, i) { g.fillText(l, x + 40, top - 6 + i * (size + 8)); });
    g.fillStyle = MUTED; g.font = '600 24px InterK'; g.fillText('СЕЙЧАС В КИНО', x + 40, y + h - 40);
  }

  function seatsLine(seats) {
    var by = {}; seats.forEach(function (s) { (by[s[0]] = by[s[0]] || []).push(s[1]); });
    return Object.keys(by).map(Number).sort(function (a, b) { return a - b; }).map(function (r) {
      var c = by[r].sort(function (a, b) { return a - b; });
      return 'Ряд ' + r + ' · ' + (c.length > 1 ? 'места ' : 'место ') + c.join(', ');
    });
  }
  function ticketsWord(n) { var a = n % 10, b = n % 100; return a === 1 && b !== 11 ? 'билет' : (a >= 2 && a <= 4 && (b < 12 || b > 14) ? 'билета' : 'билетов'); }

  function miniMap(x, y, w, h, d) {
    var rows = d.rows || 10, cols = d.cols || 16, aisles = d.aisles || [];
    var gapA = aisles.length ? w * 0.03 : 0;
    var cw = (w - gapA * aisles.length - 40) / cols, ch = (h - 40) / rows;
    var mine = {}, taken = {}, premium = {};
    (d.seats || []).forEach(function (s) { mine[s[0] + ':' + s[1]] = 1; });
    (d.taken || []).forEach(function (s) { taken[s[0] + ':' + s[1]] = 1; });
    (d.premium || []).forEach(function (s) { premium[s[0] + ':' + s[1]] = 1; });
    g.fillStyle = 'rgba(200,198,210,0.55)'; rr(x + w * 0.1, y, w * 0.8, 8, 4); g.fill();   // экран
    g.fillStyle = '#6BFF4E'; g.fillRect(x, y + 24, 5, h - 24); g.fillRect(x + w - 5, y + 24, 5, h - 24);  // выходы
    if (d.model === 'vip2' || d.model === 'imax_compact') {
      aisles.forEach(function (afterSeat, i) {
        var center = x + 20 + afterSeat * cw + gapA * (i + 0.5);
        g.fillRect(center - 2.5, y + 24, 5, h - 24);
      });
    }
    for (var r = 1; r <= rows; r++) for (var c = 1; c <= cols; c++) {
      var shift = 0; aisles.forEach(function (a) { if (c > a) shift += gapA; });
      var sx = x + 20 + (c - 1) * cw + shift, sy = y + 32 + (r - 1) * ch;
      var k = r + ':' + c;
      if (mine[k]) { g.save(); g.shadowColor = ACC; g.shadowBlur = 18; g.fillStyle = ACC; rr(sx - cw * 0.25, sy - ch * 0.25, cw * 1.34, ch * 1.28, Math.min(8, cw * 0.4)); g.fill(); g.restore(); continue; }
      g.fillStyle = taken[k] ? '#24242B' : (premium[k] ? '#A27A43' : '#3E3E48');
      rr(sx, sy, Math.max(2, cw * 0.84), Math.max(2, ch * 0.78), Math.min(6, cw * 0.25)); g.fill();
    }
  }


  function draw() {
    var d = info || {};
    if (bg) g.drawImage(bg, 0, 0, W, H); else { g.fillStyle = '#0B0B14'; g.fillRect(0, 0, W, H); }
    var vg = g.createLinearGradient(0, 0, W, 0); vg.addColorStop(0, 'rgba(6,6,12,0.35)'); vg.addColorStop(1, 'rgba(6,6,12,0.15)');
    g.fillStyle = vg; g.fillRect(0, 0, W, H);
    // пока места не выбраны — приветственная заставка зала
    if (hello && !(d.seats && d.seats.length)) { g.drawImage(hello, 0, 0, W, H); changed(); return; }
    if (!d.title) {   // данных ещё нет — просто логотип
      logo(W / 2 - 230, H / 2 - 70, 140); g.fillStyle = TXT; g.font = '800 96px Mont'; g.textBaseline = 'middle'; g.fillText('КАДР', W / 2 - 60, H / 2); changed(); return;
    }
    g.textBaseline = 'alphabetic';
    poster(94, 94, 476, 714, d);
    var X = 650;
    logo(X, 98, 74);
    g.fillStyle = TXT; g.font = '800 52px Mont'; g.fillText('КАДР', X + 90, 150);
    g.fillStyle = MUTED; g.font = '500 27px InterK'; g.fillText([d.hall, d.cinema].filter(Boolean).join(' · '), X + 92, 186);
    g.fillStyle = TXT; fitText(d.title, W - X - 90, 112, '800', 'Mont'); g.fillText(d.title, X - 4, 330);
    // плашки
    var cx = X, tags = [d.age, d.genre, d.duration, d.format].filter(Boolean);
    g.font = '600 32px InterK';
    tags.forEach(function (t) { var tw = g.measureText(t).width + 40; g.strokeStyle = 'rgba(245,243,238,0.35)'; g.lineWidth = 2.5; rr(cx, 360, tw, 54, 14); g.stroke(); g.fillStyle = TXT; g.fillText(t, cx + 20, 398); cx += tw + 16; });
    g.fillStyle = TXT; g.font = '600 44px InterK'; g.fillText((d.date || '') + (d.time ? ' · ' + d.time : ''), X, 486);
    // заполненность зала: занято / всего (свои выбранные места тоже считаются занятыми)
    var total = (d.rows || 0) * (d.cols || 0);
    if (total) {
      var busy = (d.taken || []).length + (d.seats || []).length, rx = W - 94;
      g.textAlign = 'right';
      g.fillStyle = MUTED; g.font = '600 30px InterK';
      var tail = 'свободно ' + (total - busy);
      g.fillText(tail, rx, 486);
      var tw = g.measureText(tail).width;
      g.fillStyle = TXT; g.font = '800 44px Mont';
      var mid = busy + ' / ' + total;
      g.fillText(mid, rx - tw - 28, 486);
      var mw = g.measureText(mid).width;
      g.fillStyle = MUTED; g.font = '600 30px InterK';
      g.fillText('Занято', rx - tw - 28 - mw - 18, 486);
      g.textAlign = 'left';
    }
    // панель «Ваши места»
    var px = X, py = 520, pw = W - X - 94, ph = 288;
    g.fillStyle = 'rgba(22,22,28,0.82)'; rr(px, py, pw, ph, 30); g.fill();
    var seats = d.seats || [];
    g.fillStyle = MUTED; g.font = '600 25px InterK'; g.fillText('ВАШИ МЕСТА', px + 36, py + 56);
    var textW = pw * 0.50;
    if (seats.length) {
      var lines = seatsLine(seats), size = lines.length > 2 ? 40 : (lines.length > 1 ? 50 : 62);
      g.fillStyle = ACC;
      lines.slice(0, 3).forEach(function (l, i) { fitText(l, textW, size, '800', 'Mont'); g.fillText(l, px + 34, py + 116 + i * (size + 8)); });
      var after = py + 116 + (Math.min(lines.length, 3) - 1) * (size + 8);
      g.fillStyle = TXT; g.font = '600 34px InterK';
      g.fillText(seats.length + ' ' + ticketsWord(seats.length) + (d.total ? ' · ' + d.total + ' ₽' : ''), px + 36, Math.min(after + 62, py + ph - 70));
      g.fillStyle = MUTED; g.font = '500 28px InterK'; g.fillText('Приятного просмотра!', px + 36, py + ph - 30);
    } else {
      g.fillStyle = TXT; g.font = '800 54px Mont'; g.fillText('Выберите места', px + 34, py + 126);
      g.fillStyle = MUTED; g.font = '500 30px InterK'; g.fillText('Нажмите на кресла на схеме зала', px + 36, py + 180);
    }
    miniMap(px + pw * 0.53, py + 24, pw * 0.44, ph - 48, d);
    changed();
  }
  function changed() { version++; if (window.KadrScreen && KadrScreen.onChange) KadrScreen.onChange(); }

  var ready = fontsReady();
  var hi = new Image(); hi.onload = function () { hello = hi; ready.then(draw); };
  hi.src = 'data:image/jpeg;base64,';
  var im = new Image(); im.onload = function () { bg = im; ready.then(draw); }; im.onerror = function () { ready.then(draw); };
  im.src = 'data:image/jpeg;base64,';
  return {
    canvas: cv,
    version: function () { return version; },
    set: function (d) { info = d; ready.then(draw); },
    setPoster: function (url) {
      var image = url ? new Image() : null;
      filmPoster = image;
      if (image) {
        image.onload = function () { if (filmPoster === image) ready.then(draw); };
        image.src = url;
      }
      ready.then(draw);
    },
    setWelcome: function (welcomeUrl, backgroundUrl) {
      hi.onload = null;
      im.onload = null;
      hello = null;
      bg = null;
      var welcome = new Image(), background = new Image();
      background.onload = function () { bg = background; ready.then(draw); };
      background.src = backgroundUrl;
      return new Promise(function (resolve) {
        welcome.onload = function () { hello = welcome; ready.then(draw).then(resolve); };
        welcome.onerror = resolve;
        welcome.src = welcomeUrl;
      });
    },
    redrawn: ready
  };
})();
